  function translateGeneratedEditableValue(value) {
    if (!value || typeof value !== "string") {
      return value;
    }
    var trimmed = normalize(value);
    var generatedMap = {
      "<calculated at runtime>": "<calculated at runtime>",
      "<calculated when request is sent>": "<calculated when request is sent>",
      "calculated at runtime": "calculated at runtime",
      "calculated when request is sent": "calculated when request is sent"
    };
    if (Object.prototype.hasOwnProperty.call(generatedMap, trimmed)) {
      return preserveOuter(value, generatedMap[trimmed]);
    }
    var forkMatch = trimmed.match(/^(.{1,80})['\u2019]s fork$/i);
    if (forkMatch) {
      return forkMatch[1] + " 的派生";
    }
    return value;
  }

