  function translatePublicApiNetworkSearchScope(scope) {
    var value = normalize(scope).replace(/[’']/g, "").replace(/^for\s+/i, "").toLowerCase();
    var compact = value.replace(/\s+/g, "");
    var map = {
      "anything": "任何内容",
      "everything": "全部内容",
      "api": "API",
      "apis": "API",
      "collection": "集合",
      "collections": "集合",
      "workspace": "工作区",
      "workspaces": "工作区",
      "workpace": "工作区",
      "workpaces": "工作区",
      "team": "团队",
      "teams": "团队",
      "request": "请求",
      "requests": "请求",
      "environment": "环境",
      "environments": "环境",
      "mockserver": "模拟服务器",
      "mockservers": "模拟服务器",
      "monitor": "监视器",
      "monitors": "监视器",
      "user": "用户",
      "users": "用户",
      "example": "示例",
      "examples": "示例"
    };
    if (Object.prototype.hasOwnProperty.call(map, compact)) {
      return map[compact];
    }
    var translated = normalize(translate(scope));
    return translated || scope;
  }

