        "folder": "文件夹",
        "flow": "Flow",
        "mock": "模拟服务器",
        "mock server": "模拟服务器",
        "monitor": "监视器",
        "request": "请求",
        "spec": "规范",
        "specification": "规范",
        "workspace": "工作区"
